"use client";

import React, { useEffect, useState } from 'react';
import { AuditProgress } from '@/components/audit/audit-progress';
import { AuditHeader } from '@/components/audit/audit-header';
import { StrategicGaps } from '@/components/audit/strategic-gaps';
import { StrategyRoadmap } from '@/components/audit/strategy-roadmap';
import { CompetitorLandscape } from '@/components/audit/competitor-landscape';
import { AlertCircle } from 'lucide-react';

export default function AuditDashboardPage({ params }: { params: { username: string } }) {
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(true);

  useEffect(() => {
    let intervalId: NodeJS.Timeout;

    const fetchAudit = async () => {
      try {
        const res = await fetch(`/api/audit/${params.username}`);
        if (!res.ok) throw new Error("Failed to fetch audit data");
        const json = await res.json();

        if (json.status === "processing") {
          setIsProcessing(true);
        } else if (json.status === "complete") {
          setIsProcessing(false);
          setData(json);
          clearInterval(intervalId);
        } else {
          throw new Error("Unknown status returned");
        }
      } catch (err: any) {
        setError(err.message);
        clearInterval(intervalId);
      }
    };

    // Initial fetch
    fetchAudit();

    // Poll every 3 seconds if processing
    intervalId = setInterval(() => {
      if (isProcessing && !data && !error) {
        fetchAudit();
      }
    }, 3000);

    return () => clearInterval(intervalId);
  }, [params.username, isProcessing, data, error]);

  if (error) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-4">
        <div className="bg-rose-500/10 border border-rose-500/20 text-rose-400 p-6 rounded-2xl flex items-center gap-3">
          <AlertCircle className="w-8 h-8" />
          <div>
            <h2 className="font-bold text-lg">Audit Failed</h2>
            <p>{error}</p>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing || !data) {
    return (
      <div className="min-h-screen bg-slate-950 py-20">
        <AuditProgress />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 selection:bg-indigo-500/30">
      <div className="max-w-5xl mx-auto px-4 py-12 md:py-20 space-y-12">
        {/* Module 1: Identity Intelligence */}
        <section>
          <AuditHeader username={data.profile.username} intelligence={data.intelligence} />
        </section>

        {/* Module 2: Strategic Assessment */}
        {data.strategy && (
          <section>
            <StrategicGaps strategicGap={data.strategy.strategicGap} />
          </section>
        )}

        {/* Module 3: Growth Roadmap */}
        {data.strategy && (
          <section>
            <StrategyRoadmap roadmap={data.strategy.strategyRoadmap} />
          </section>
        )}

        {/* Module 4: Competitor Landscape */}
        <section>
          <CompetitorLandscape competitors={data.competitors} />
        </section>
      </div>
    </div>
  );
}
